import{_ as t,c as e,o as r,ah as o}from"./chunks/framework.l36K22_3.js";const f=JSON.parse('{"title":"CSS 之 BFC","description":"","frontmatter":{},"headers":[],"relativePath":"tiku/html-css/page3.md","filePath":"tiku/html-css/page3.md","lastUpdated":1730255929000}'),n={name:"tiku/html-css/page3.md"};function s(l,a,c,h,i,d){return r(),e("div",null,a[0]||(a[0]=[o('<h1 id="css-之-bfc" tabindex="-1">CSS 之 BFC <a class="header-anchor" href="#css-之-bfc" aria-label="Permalink to &quot;CSS 之 BFC&quot;">​</a></h1><h2 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h2><p>在解释 BFC 之前，先说一下文档流。我们常说的文档流其实分为定位流、浮动流、普通流三种。而普通流其实就是指 BFC 中的 FC。FC(Formatting Context)，直译过来是格式化上下文，它是页面中的一块渲染区域，有一套渲染规则，决定了其子元素如何布局，以及和其他元素之间的关系和作用。常见的 FC 有 BFC、IFC，还有 GFC 和 FFC。</p><p><strong>BFC(Block Formatting Context)块级格式化上下文</strong>，是用于布局块级盒子的一块渲染区域。MDN 上的解释：BFC 是 Web 页面 CSS 视觉渲染的一部分，用于决定块盒子的布局及浮动相互影响范围的一个区域。</p><p>注意：一个 BFC 的范围包含创建该上下文元素的所有子元素，但不包括创建了新 BFC 的子元素的内部元素。这从另一方角度说明，一个元素不能同时存在于两个 BFC 中。因为如果一个元素能够同时处于两个 BFC 中，那么就意味着这个元素能与两个 BFC 中的元素发生作用，就违反了 BFC 的隔离作用。</p><h2 id="精选文章" tabindex="-1">精选文章 <a class="header-anchor" href="#精选文章" aria-label="Permalink to &quot;精选文章&quot;">​</a></h2><h3 id="mdn-块格式化上下文-block-formatting-context-bfc" tabindex="-1"><a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/CSS_display/Block_formatting_context" target="_blank" rel="noreferrer">MDN：块格式化上下文（Block Formatting Context，BFC）</a> <a class="header-anchor" href="#mdn-块格式化上下文-block-formatting-context-bfc" aria-label="Permalink to &quot;[MDN：块格式化上下文（Block Formatting Context，BFC）](https://developer.mozilla.org/zh-CN/docs/Web/CSS/CSS_display/Block_formatting_context)&quot;">​</a></h3><h3 id="「百毒不侵」面试官最喜欢问的-6-种清除浮动和-bfc" tabindex="-1"><a href="https://juejin.cn/post/6982179919597928485" target="_blank" rel="noreferrer">「百毒不侵」面试官最喜欢问的 6 种清除浮动和 BFC</a> <a class="header-anchor" href="#「百毒不侵」面试官最喜欢问的-6-种清除浮动和-bfc" aria-label="Permalink to &quot;[「百毒不侵」面试官最喜欢问的 6 种清除浮动和 BFC](https://juejin.cn/post/6982179919597928485)&quot;">​</a></h3><h3 id="css-中重要的-bfc" tabindex="-1"><a href="https://segmentfault.com/a/1190000013023485" target="_blank" rel="noreferrer">CSS 中重要的 BFC</a> <a class="header-anchor" href="#css-中重要的-bfc" aria-label="Permalink to &quot;[CSS 中重要的 BFC](https://segmentfault.com/a/1190000013023485)&quot;">​</a></h3><h3 id="「bfc」块级格式化上下文-到底是个啥" tabindex="-1"><a href="https://juejin.cn/post/7019318292603600909" target="_blank" rel="noreferrer">「BFC」块级格式化上下文 到底是个啥？？？</a> <a class="header-anchor" href="#「bfc」块级格式化上下文-到底是个啥" aria-label="Permalink to &quot;[「BFC」块级格式化上下文 到底是个啥？？？](https://juejin.cn/post/7019318292603600909)&quot;">​</a></h3><h3 id="css-深入理解流体特性和-bfc-特性下多栏自适应布局" tabindex="-1"><a href="https://www.zhangxinxu.com/wordpress/2015/02/css-deep-understand-flow-bfc-column-two-auto-layout/" target="_blank" rel="noreferrer">CSS 深入理解流体特性和 BFC 特性下多栏自适应布局</a> <a class="header-anchor" href="#css-深入理解流体特性和-bfc-特性下多栏自适应布局" aria-label="Permalink to &quot;[CSS 深入理解流体特性和 BFC 特性下多栏自适应布局](https://www.zhangxinxu.com/wordpress/2015/02/css-deep-understand-flow-bfc-column-two-auto-layout/)&quot;">​</a></h3>',11)]))}const p=t(n,[["render",s]]);export{f as __pageData,p as default};
